from taf.nms.nom.schemas.base import SchemaObject, SchemaField
from taf.nms.nom.schemas.fm.alarm import Alarm


class AlarmSearchPageResponse(SchemaObject):
    description = SchemaField(name="description")
    alarms = SchemaField(name="alarms", many=True, klass=Alarm)
    next = SchemaField(name="next")
    count = SchemaField(name="count", not_null=True)

    def __init__(self, description, alarms, next, count):
        self.description = description
        self.alarms = alarms if alarms else []
        self.next = next if next else []
        self.count = count
        super(AlarmSearchPageResponse, self).__init__()
